45	export function parseAcrossReleases(names: readonly string[], argv: readonly string[]): Record<string, string> {
46	  const known = new Set(names);
47	  const values: Record<string, string> = Object.fromEntries(names.map((name) => [name, ""]));
48	  const ignored: string[] = [];
49	  for (let index = 0; index < argv.length; index += 1) {
50	    const token = argv[index] ?? "";
51	    if (!token.startsWith("--")) continue;
52	    const [flag, inline] = splitFlag(token.slice(2));
53	    const value = inline ?? argv[index + 1] ?? "";
54	    if (inline === undefined) index += 1;
55	    if (known.has(flag)) values[flag] = value;
56	    else ignored.push(flag);
57	  }
58	  if (ignored.length > 0) {
59	    console.error(
60	      `::warning::Ignored ${ignored.map((flag) => `\`--${flag}\``).join(", ")}: this script is from an ` +
61	        "older release than the workflow that ran it. It will understand them once the upgrade reaches " +
62	        "the default branch.",
63	    );
64	  }
65	  return values;
66	}
