68	/** `name=value` written as one token, or just the name. */
69	function splitFlag(token: string): [string, string | undefined] {
70	  const at = token.indexOf("=");
71	  return at === -1 ? [token, undefined] : [token.slice(0, at), token.slice(at + 1)];
72	}
