74	export function toArgv<T extends Record<string, string | number | boolean | undefined>>(args: T): string[] {
75	  const argv: string[] = [];
76	  for (const [flag, value] of Object.entries(args)) {
77	    if (value === undefined) continue;
78	    // Double-quote every value: these argv arrays are joined with spaces and
79	    // spliced directly into a bash `run:` heredoc, so a value that is itself a
80	    // `${VAR}`/`${{ ... }}` expansion has to stay quoted or it word-splits.
81	    //
82	    // Quoting is NOT a safety boundary, and reading it as one is how an
83	    // injection gets written. Double quotes stop word splitting and globbing;
84	    // they do not stop `$(...)`, backticks, or `${...}`, all of which still
85	    // expand inside them. For a `${{ }}` expression that is doubly true: the
86	    // value is substituted into the script TEXT before bash parses it, so a
87	    // quote character in the value simply ends the string.
88	    //
89	    // What makes these call sites safe is therefore the value's provenance, not
90	    // this function. Values reaching a generated `run:` must be validated
91	    // before they get here -- see atomaton-runner.wac.ts's "Validate workflow
92	    // inputs" step, which is the boundary for every input that workflow splices
93	    // into shell text.
94	    argv.push(`--${flag}`, `"${String(value)}"`);
95	  }
96	  return argv;
97	}

