56	import { LLM_CONTEXT_TAG, STOP_TAG } from "../../adapters/github/tags.ts";
57	import { openClaimStopState } from "../../adapters/github/thread.ts";
58	import { commentOn } from "../../adapters/github/work-tree.ts";
59	import { stopOnPullRequestCloseNotice } from "../../domain/work/closed-target.ts";
60	import { isTrue } from "./lib/flags.ts";
61	import { defineScript } from "./lib/script-ref.ts";
62	
63	export interface StopOnPrCloseArgs {
64	  number: string | number;
65	  /** `true` when the close was a merge. Both outcomes of `closed` are a close. */
66	  merged: string | boolean;
67	}
